import React, { useState, useCallback } from 'react';
import { Droppable, Draggable, DragDropContext, DropResult } from '@hello-pangea/dnd';
import { Recipe } from './RecipeList';
import './WeeklyMeals.css';

interface WeeklyMealsProps {
  className?: string;
  onMealsChange: (meals: Recipe[]) => void;
  onRecipeDrop?: (recipe: Recipe) => void;
}

const WeeklyMeals: React.FC<WeeklyMealsProps> = ({ className, onMealsChange }) => {
  const [meals, setMeals] = useState<Recipe[]>([]);
  const [isContainerCollapsed, setIsContainerCollapsed] = useState(false);

  const addMeal = useCallback((recipe: Recipe) => {
    setMeals(prev => {
      const newMeals = [...prev, recipe];
      onMealsChange(newMeals);
      return newMeals;
    });
  }, [onMealsChange]);

  const removeMeal = useCallback((mealId: string) => {
    setMeals(prev => {
      const newMeals = prev.filter(meal => meal.id !== mealId);
      onMealsChange(newMeals);
      return newMeals;
    });
  }, [onMealsChange]);

  const onDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;

    const newMeals = Array.from(meals);
    const [reorderedMeal] = newMeals.splice(result.source.index, 1);
    newMeals.splice(result.destination.index, 0, reorderedMeal);

    setMeals(newMeals);
    onMealsChange(newMeals);
  }, [meals, onMealsChange]);

  // This function will be called from parent when a recipe is dropped
  const handleRecipeDrop = useCallback((recipe: Recipe) => {
    addMeal(recipe);
  }, [addMeal]);

  // Expose the handleRecipeDrop function to parent
  React.useImperativeHandle(React.createRef(), () => ({
    handleRecipeDrop
  }));

  return (
    <div className={`weekly-meals-container ${className || ''} ${isContainerCollapsed ? 'collapsed' : ''}`}>
      <div className="container-header" onClick={() => setIsContainerCollapsed(!isContainerCollapsed)}>
        <h2>Weekly Meals</h2>
        <span className={`container-expand-icon ${isContainerCollapsed ? '' : 'expanded'}`}>◀</span>
      </div>
      
      <div className={`container-content ${isContainerCollapsed ? 'collapsed' : 'expanded'}`}>
        <p className="meals-instruction">Drag recipes here for meal planning</p>
        
        <DragDropContext onDragEnd={onDragEnd}>
          <Droppable droppableId="weekly-meals">
            {(provided, snapshot) => (
              <div
                {...provided.droppableProps}
                ref={provided.innerRef}
                className={`meals-container ${snapshot.isDraggingOver ? 'dragging-over' : ''}`}
              >
                {meals.length === 0 ? (
                  <div className="empty-meals">
                    <p>No meals planned</p>
                    <p>Drag recipes here to plan your week</p>
                  </div>
                ) : (
                  meals.map((meal, index) => (
                    <Draggable key={`meal-${meal.id}-${index}`} draggableId={`meal-${meal.id}-${index}`} index={index}>
                      {(provided, snapshot) => (
                        <div
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          className={`meal-item ${snapshot.isDragging ? 'dragging' : ''}`}
                        >
                          <div {...provided.dragHandleProps} className="drag-section">
                            <span className="drag-handle">⋮⋮</span>
                            <span className="meal-emoji">{meal.emoji}</span>
                            <div className="meal-details">
                              <div className="meal-name">{meal.name}</div>
                              <div className="meal-category">{meal.category}</div>
                              <div className="meal-ingredients">
                                {meal.ingredients.join(', ')}
                              </div>
                            </div>
                          </div>
                          <button 
                            className="remove-meal-btn"
                            onClick={() => removeMeal(meal.id)}
                            title="Remove from meal plan"
                          >
                            ×
                          </button>
                        </div>
                      )}
                    </Draggable>
                  ))
                )}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>
      </div>
    </div>
  );
};

export default WeeklyMeals;
